package com.yonlab.offlinevoice;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** Pinned four-file manifest and exact archive transaction for converted MIT Whisper weights. */
final class WhisperModelStore {
 static final String MANIFEST_SHA="c309e3ad92d59bcbcf959f59f995bf2954c337ad5fb2766ed1432ac6968047a5",ZIP_SHA="5001b4a0e90a068c78f079d613e91e3e58fc36be0350b19ce3dc651bdd599849",PREFIX="sherpa-whisper-tiny-int8/";
 static final long ZIP_BYTES=59484816L,UNPACKED_BYTES=103610966L;private WhisperModelStore(){}
 static File prepare(Context context,SafeModelZip.Cancel cancel)throws Exception{synchronized(KoreanModelStore.class){
  byte[] raw;try(InputStream input=context.getAssets().open("offlinevoice/whisper-model-files.json");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[4096];int n;while((n=input.read(block))!=-1){SafeModelZip.check(cancel);if(out.size()+n>65536)throw new IOException("Whisper manifest size");out.write(block,0,n);}raw=out.toByteArray();}if(!MANIFEST_SHA.equals(SafeModelZip.hex(MessageDigest.getInstance("SHA-256").digest(raw))))throw new IOException("Whisper manifest hash");
  JSONObject manifest=new JSONObject(new String(raw,StandardCharsets.UTF_8));if(!VoiceModelPolicy.WHISPER.equals(manifest.getString("model")))throw new IOException("Whisper model identity");JSONArray files=manifest.getJSONArray("files");Map<String,SafeModelZip.Expected> expected=new LinkedHashMap<>();Set<String> allowed=new HashSet<>(Arrays.asList("tiny-encoder.int8.onnx","tiny-decoder.int8.onnx","tiny-tokens.txt","LICENSE-Whisper.txt"));long total=0;for(int i=0;i<files.length();i++){JSONObject row=files.getJSONObject(i);String path=row.getString("path");SafeModelZip.Expected item=new SafeModelZip.Expected(row.getLong("bytes"),row.getString("sha256"));if(!allowed.contains(path)||expected.put(path,item)!=null)throw new IOException("Whisper manifest file");total+=item.bytes;}if(files.length()!=4||total!=UNPACKED_BYTES)throw new IOException("Whisper manifest shape");
  File base=new File(context.getNoBackupFilesDir(),"offlinevoice-models");if(!base.isDirectory()&&!base.mkdirs())throw new IOException("Whisper storage");SafeModelZip.cleanupPending(base,cancel);File target=new File(base,"whisper-tiny-"+MANIFEST_SHA.substring(0,12));if(SafeModelZip.verify(target,expected,cancel))return target;if(target.exists())SafeModelZip.removeOwned(base,target);if(base.getUsableSpace()<UNPACKED_BYTES+ZIP_BYTES+16L*1024*1024)throw new IOException("Whisper storage space");String uid=UUID.randomUUID().toString();File pending=new File(base,"pending-"+uid),archive=new File(base,"pending-"+uid+".zip");
  try{MessageDigest digest=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream input=context.getAssets().open("offlinevoice/whisper-tiny-multilingual-int8.zip");FileOutputStream output=new FileOutputStream(archive)){byte[] block=new byte[65536];int n;while((n=input.read(block))!=-1){SafeModelZip.check(cancel);count+=n;if(count>ZIP_BYTES)throw new IOException("Whisper archive size");digest.update(block,0,n);output.write(block,0,n);}output.getFD().sync();}if(count!=ZIP_BYTES||!ZIP_SHA.equals(SafeModelZip.hex(digest.digest())))throw new IOException("Whisper archive hash");SafeModelZip.unpack(archive,pending,expected,cancel,PREFIX);SafeModelZip.check(cancel);if(!SafeModelZip.verify(pending,expected,cancel))throw new IOException("Whisper file hash");if(target.exists()||!pending.renameTo(target))throw new IOException("Whisper model commit");return target;}finally{if(archive.exists())SafeModelZip.removeOwned(base,archive);if(pending.exists())SafeModelZip.removeOwned(base,pending);}
 }}
}
